def verify():
    assert abs(400 * 1.3 ** 3 - 878.8) < 0.1 and 200 * 2 * 0.25 == 100
    b = lambda n, a: (a ** n / math.factorial(n)) / sum(a ** k / math.factorial(k) for k in range(n + 1))
    assert abs(b(3, 1) - 0.0625) < 1e-12 and abs(700 / 0.7 - 1000) < 1e-9 and abs(1 / 20 - 0.05) < 1e-12
    assert abs(1 - 0.01 ** 2 - 0.9999) < 1e-12 and abs(0.999 ** 3 - 0.997) < 0.0001
    assert 2 ** 5 - 2 == 30 and math.ceil(10000 / (math.pi * 900)) == 4 and 300 // 25 == 12


if __name__ == "__main__":
    verify()
    write_subject(SUBJECT, U)
